        ConfigOption(key: "env.MADEIRA_HIDPAD_XINPUT", title: "HID 模式：玩家 1 同时保留 XInput", kind: .bool, defaultValue: "0", category: "控制器", note: "设为 1 时，开启 HID 控制器后玩家 1 仍保留 XInput 手柄。默认关闭，以免同时读取两种 API 的游戏重复识别同一手柄。", choices: [], sources: ["app/Madeira/GamepadInput.swift"]),
        ConfigOption(key: "env.MADEIRA_PAD_MODE", title: "控制器 API（玩家 1）", kind: .choice, defaultValue: "", category: "控制器", note: "默认 XInput：所有控制器表现为 Xbox 手柄。hid：玩家 1 改用 HID；PlayStation 手柄识别为 DualSense（054C:0CE6），其他手柄识别为通用 HID，并退出 XInput。dualsense/generic 强制对应身份。会话启动时读取，游戏专用配置优先。", choices: [("", "XInput（默认）"), ("hid", "DirectInput / HID"), ("dualsense", "HID，始终作为 DualSense"), ("generic", "HID，始终作为通用手柄")], sources: ["app/Madeira/GamepadInput.swift"]),
        ConfigOption(key: "env.MADEIRA_PAD_OUTPUT", title: "向手柄传递振动、自适应扳机和灯条效果", kind: .choice, defaultValue: "", category: "控制器", note: "默认开启：通过 CoreHaptics 输出 XInput 振动；DualSense HID 模式下，将游戏输出报告转换为振动、自适应扳机（最接近的 GameController 模式）、灯条和玩家指示灯。hid 仅输出 DualSense 效果；xinput 仅输出 XInput 振动；0 全部关闭。会话启动时读取，游戏专用配置优先。", choices: [("", "开启（默认）"), ("hid", "仅 DualSense 输出"), ("xinput", "仅 XInput 振动"), ("0", "关闭")], sources: ["app/Madeira/GamepadInput.swift", "app/Madeira/PadOutput.m"]),
        ConfigOption(key: "env.MADEIRA_WGI_HOST_PADS", title: "通过 Windows.Gaming.Input 访问控制器", kind: .bool, defaultValue: "0", category: "控制器", note: "默认关闭。设为 1 后，已连接的 XInput 控制器（实体或触控）也会作为支持振动的 Xbox 手柄出现在 Windows.Gaming.Input 中，适用于只使用此 API 的游戏，例如《地平线：零之曙光》。同时读取 XInput 的游戏可能重复列出手柄。游戏首次请求手柄时读取。", choices: [], sources: ["wine/dlls/windows.gaming.input/provider.c"]),
        ConfigOption(key: "env.MADEIRA_BAND_CENSUS", title: "按区域记录 64 GB 地址空间", kind: .bool, defaultValue: "0", category: "调试与日志", note: "默认关闭。开启后约每分钟以及大块预留失败时，记录 [0x7000000000, 0x8000000000) 各区域的占用、最大空闲间隙，以及能否容纳《荒野大镖客：救赎 2》的 8960 MB 预留区域，最多记录 64 次。仅输出 [band] 诊断，不改变内存位置。会话启动时读取。", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_EC_HOOK_TRACE", title: "记录模拟副本遗漏的代码补丁", kind: .bool, defaultValue: "0", category: "调试与日志", note: "默认关闭，仅记录日志。开启后在同步前比较 PE 可执行节与池中副本，包括 x64 入口跳板；独立日志配额保留原生启动重写后的图形跳转记录。发现差异本身不能证明存在内联钩子。", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_IMAGE_PATCH_TRACE", title: "DLL 代码补丁跟踪", kind: .bool, defaultValue: "0", category: "调试与日志", note: "设为 1 后，最多记录 64 次成功的 1–16 字节可执行映像保护请求及对应 PE/池字节。此诊断只读并识别所属程序，不修改钩子或代码。", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_LEAN_DIAG", title: "精简诊断（不暂停线程采样）", kind: .bool, defaultValue: "0", category: "调试与日志", note: "默认关闭。开启后停止需要暂停线程的采样器（thread-sample、rip-profile/cpu-split、wprof）；预热器地址空间扫描由每分钟改为约每 10 分钟，区域检查和分配探测由每 2 秒改为每分钟；mprotect_exec 的 ERR 日志保留前 200 次，之后每 1000 次记录一次。xp、xp-t、xp-api、sync-census 频率不变。会话启动时读取。", choices: [], sources: ["build/ntdll-unix/server_ios.c", "build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_POWER_PROBE", title: "每 5 秒记录 GPU 和设备功耗", kind: .bool, defaultValue: "0", category: "调试与日志", note: "默认关闭，不读取功耗数据。开启后每 5 秒在 [xp] CPU 能耗旁记录 GPU 能耗与时间、SoC 能耗模型计数器、断开电源时整机电池电压和电流，并在 [power-t] 中列出耗能最多的线程。系统不提供的数据源只报告一次不可用。需要 [xp] 采样器，会话启动时读取。", choices: [], sources: ["build/ntdll-unix/server_ios.c"]),
        ConfigOption(key: "addr-scan", title: "加快 GPU 地址查询", kind: .bool, defaultValue: "1", category: "Direct3D 12", note: "默认开启。查找 GPU 地址所属缓冲区时，只向后遍历仍可能覆盖该地址的条目，避免遍历最大缓冲区范围内的全部条目；结果保持不变。设为 0 恢复原遍历方式。每次游戏启动时读取。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "ags-rewrite", title: "重写 D3D12 AMD AGS 64 位原子操作", kind: .text, defaultValue: "", category: "Direct3D 12", note: "D3D12 AMD AGS 64 位原子操作重写开关，只读取一次。在 madeira.cfg 中设置 ags-rewrite = 0 可关闭。", choices: [], sources: ["madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "async-present-ahead", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "限制提前提交的呈现帧数。Present 入队后返回，应用可准备下一帧；工作线程后方最多排队指定数量的帧，默认 1。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "async-submit", title: "D3D12 异步提交", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "启用 Direct3D 12 异步提交（ml1120）。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "barrier-render", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "设为 1 时，屏障处理也会结束当前渲染通道；属于保守的兼容性实验。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "capture-big", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "帧捕获时是否包含大渲染目标。默认跳过超过 16 MB 的目标，设为 1 时也捕获这些目标。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "capture-cs", title: "", kind: .text, defaultValue: "", category: "Direct3D 12", note: "每次执行 CAP 帧捕获时重新读取计算着色器目标，使同一次运行中可以更换捕获目标。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "capture-cs-indirect", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "每次执行 CAP 帧捕获时重新读取间接计算着色器捕获设置。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "capture-cs-max", title: "", kind: .int, defaultValue: "12", category: "Direct3D 12", note: "每次执行 CAP 帧捕获时重新读取计算着色器捕获数量上限。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "capture-ps", title: "", kind: .text, defaultValue: "", category: "Direct3D 12", note: "与 capture-cs 一样，每次执行 CAP 帧捕获时重新读取像素着色器目标。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "capture-raw", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "帧捕获的原始图像输出选项，用于制作捕获预览图集。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "capture-uav", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "帧捕获的 UAV 输出选项，用于制作捕获预览图集。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "cbv-snapshot", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "实验性修复：回放时复制每个上传堆根 CBV 的前 N 字节，并绑定副本；值为 1 时表示 4096 字节。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "clear-defer", title: "延迟清除，直到对应目标开始绘制", kind: .bool, defaultValue: "1", category: "Direct3D 12", note: "默认开启。完整渲染目标或深度模板清除会合并为下次绘制该目标时的渲染通道起始清除，避免创建独立通道及额外内存读写。涉及该纹理的屏障、复制或其他视图会先执行清除，保证后续读取正确。设为 0 恢复每次清除结束当前通道并单独执行的方式。每次游戏启动时读取。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "clear-rects", title: "仅清除游戏请求的矩形区域", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "默认关闭，带矩形参数的渲染目标或深度模板清除仍清除整个视图。设为 1 时，通过独立的小通道只清除请求的矩形；覆盖整个视图的矩形仍使用快速方式。《地平线：零之曙光》从最初的游戏画面起就会请求矩形清除。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "cs-dump", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "d3d12-binding-tier", title: "报告的资源绑定层级", kind: .int, defaultValue: "2", category: "Direct3D 12", note: "默认报告资源绑定层级 2。设为 3 后，OPTIONS 报告层级 3，与 Apple D3DMetal 和 vkd3d-proton 一致，游戏可能因此使用不同的绑定路径。其他值仍为层级 2。每次游戏启动时读取。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "d3d12-caps-log", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "D3D12 能力查询日志；设为 2 时也记录格式查询。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "d3d12-core-dll", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "设为 1 时按 Agility SDK 布局加载 d3d12core.dll；大于 1 时还读取其 D3D12SDKVersion。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "d3d12-msaa8", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "设为 1 时向游戏报告支持 8 倍 MSAA，但实际按 4 倍 MSAA 渲染。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "d3d12-raw-typed-views", title: "允许按类型读取原始缓冲区视图", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "默认关闭。开启后，原始和结构化缓冲区视图也带有纹理缓冲区视图（R32；步长允许的结构化 SRV 使用 RG32/RGBA32），使以 Buffer<T> 读取的着色器获得实际数据而非零。每个此类视图会额外创建一个 Metal 纹理对象。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "d3d12-reserved-max-mb", title: "", kind: .int, defaultValue: "1024", category: "Direct3D 12", note: "允许完整分配后备内存的保留资源最大大小，单位 MB。超出该大小返回 E_OUTOFMEMORY。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "d3d12-shader-pack", title: "将 D3D12 着色器缓存存入两个包文件", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "默认关闭，转换后的着色器各自保存为 Documents/shadercache 中的文件。开启后，DXBC 和 DXIL 缓存分别存入只追加的 shadercache/pack/dxbc.mdpk、dxil.mdpk；旧散文件在游戏使用时迁入。再次关闭后不读取包，已迁入的着色器会重新转换。DXIL 上限由 env.MADEIRA_D3D12_DXIL_CACHE_MB 指定（默认 512 MB），DXBC 上限 2 GB，包满后重建。应用启动时读取，游戏专用配置优先。", choices: [], sources: ["madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "d3d12-tile-based", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "设为 0 时，将 TileBasedRenderer 报告为 FALSE，与桌面 GPU 的报告方式一致。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "d3d12-tiled-resources", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "可选平铺资源支持：报告 TiledResourcesTier 2、每个资源 40 位虚拟地址、R32G32B32 顶点格式，并为保留资源完整分配后备内存。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "d3d12-typed-uav-load", title: "D3D12 类型化 UAV 加载（报告支持）", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "FORMAT_SUPPORT 已为所有未压缩颜色格式报告 UAV_TYPED_LOAD（Metal 可读写纹理），但此选项默认仍关闭：报告支持可能让已正常运行的引擎切换到不同渲染路径。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "d3d12-wave-ops", title: "报告波前操作支持", kind: .bool, defaultValue: "1", category: "Direct3D 12", note: "默认开启。设为 0 后，OPTIONS1 报告不支持 WaveOps，有回退方案的游戏会选择不使用波前内置函数的着色器，可用于对比着色器转换器的波前代码。《地平线：零之曙光》会读取此能力。每次游戏启动时读取。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "desc-guard", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "描述符诊断：记录对仍被运行中批次使用的、着色器可见槽位的写入。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "draw-dedup", title: "跳过编码器已有的渲染状态", kind: .bool, defaultValue: "1", category: "Direct3D 12", note: "默认开启。跳过渲染编码器已保留的管线、视口、裁剪、深度模板、混合颜色、光栅和缓冲区绑定状态；同一缓冲区仅偏移变化时只更新偏移。每次绘制仍使用完整正确状态。设为 0 恢复每次发送所有状态。每次游戏启动时读取。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "dump-shaders", title: "", kind: .text, defaultValue: "", category: "Direct3D 12", note: "导出指定着色器，名称以逗号分隔。输出为 Documents/capture/shader_<名称>.dxbc，在缓存查询前写入，因此也能导出已缓存着色器。", choices: [], sources: ["madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "dxbc-register-spaces", title: "着色器模型 5.1 支持非 0 寄存器空间", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "默认关闭，拒绝在非 0 寄存器空间声明资源的着色器模型 5.1 DXBC 着色器，不创建对应管线。开启后按根签名中相同空间和寄存器绑定资源，并使用独立缓存。《地平线：零之曙光》的常量缓冲区位于空间 6 和 8，需要此项。每次会话读取。", choices: [], sources: ["madeira-d3d12/src/unix/madeira_ir_unix.mm", "madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "dxil-dump", title: "", kind: .text, defaultValue: "", category: "Direct3D 12", note: "DXIL 诊断：记录具有指定入口名称的管线字节码。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "dxil-tess", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "DXIL 曲面细分模拟：将顶点、外壳与域着色器转换为 Metal 对象与网格函数，并链接所需的细分函数。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "dxil-tess-max-factor", title: "", kind: .int, defaultValue: "3", category: "Direct3D 12", note: "限制模拟曲面细分的最大因子。大量粒子四边形会生成许多三角形，提高因子可能显著增加 GPU 开销。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "encode-batch", title: "每个编码器仅调用一次 Metal", kind: .bool, defaultValue: "1", category: "Direct3D 12", note: "默认开启。将一个 Metal 编码器的状态、绘制及栅栏等待/更新命令先排队，再在编码器结束时一次性交给 Metal 桥接层，保持命令和顺序一致。可减少每帧桥接次数。设为 0 恢复每次绘制调用一次，便于排查回归。每次游戏启动时读取。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "encoder-labels", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "为每个 Metal 编码器设置包含序列号与着色器名称的标签，以便 Instruments 按渲染通道分析 GPU 时间。默认关闭。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "env.MADEIRA_AGS_ROUNDTRIP_ONLY", title: "", kind: .text, defaultValue: "", category: "Direct3D 12", note: "设为 0 时，转换着色器时不启用 D3D12 稳健缓冲区访问的边界检查，对应 MADEIRA_IR_NO_BOUNDS_CHECK=1。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c", "madeira-d3d12/src/unix/madeira_ags.cpp"]),
        ConfigOption(key: "env.MADEIRA_APP_IMAGE_UUID", title: "", kind: .text, defaultValue: "", category: "Direct3D 12", note: "由应用设置的可执行映像 UUID，不是功能开关。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "env.MADEIRA_D3D12_CS_DUMP", title: "", kind: .text, defaultValue: "", category: "Direct3D 12", note: "D3D12 计算着色器导出诊断。每次运行向 C:\\madeira-cs 写入大量文件会增加启动时间，仅用于排查特定内核。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "env.MADEIRA_D3D12_DXIL_CACHE", title: "", kind: .bool, defaultValue: "", category: "Direct3D 12", note: "", choices: [], sources: ["madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "env.MADEIRA_D3D12_DXIL_CACHE_MB", title: "", kind: .text, defaultValue: "", category: "Direct3D 12", note: "", choices: [], sources: ["madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "env.MADEIRA_D3D12_ONEPASS", title: "", kind: .bool, defaultValue: "", category: "Direct3D 12", note: "将原先的“两次调用：查询大小再填充”改为一次转换。初始缓冲区按输入大小的四倍加 64 KB 分配，减少重复执行编译器。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c", "madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "env.MADEIRA_D3D12_RS_DESERIALIZER", title: "", kind: .text, defaultValue: "", category: "Direct3D 12", note: "D3D12 根签名反序列化路径开关。仅首次读取，用于无需重新编译即可隔离设备回归问题。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "env.MADEIRA_D3D12_TYPED_UAV_LOAD", title: "", kind: .text, defaultValue: "", category: "Direct3D 12", note: "是否报告额外的带类型 UAV 读取能力。虽然格式查询已报告未压缩颜色格式支持此能力，默认仍关闭该选项，避免游戏切换到不同渲染路径。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "env.MADEIRA_IR_NO_BOUNDS_CHECK", title: "", kind: .text, defaultValue: "", category: "Direct3D 12", note: "转换器读取的配置开关，包括位置不变性、严格 NaN/Inf 处理与采样器 LOD 偏移。可在 madeira.cfg 中以 env.NAME 或环境变量设置。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c", "madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "env.MADEIRA_MSC_DYLIB", title: "", kind: .text, defaultValue: "", category: "Direct3D 12", note: "仅限主机构建：让离线往返测试指定解包后的转换器路径。设备构建不包含此入口，运行时只从固定位置加载转换器。", choices: [], sources: ["madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "env.MADEIRA_X64_GRAPHICS_ENTRY", title: "可打补丁的 x64 图形方法入口", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "默认关闭。开启后，为交换链 Present/Present1、ResizeBuffers/ResizeBuffers1，以及队列 ExecuteCommandLists/GetTimestampFrequency/GetClockCalibration/GetDesc/Signal/Wait 暴露类型化 x64 ARM64EC 入口。DXMT dxgi 支持时也选择可打补丁的工厂入口。入口使用加载器的 PE 地址，保持补丁与附近分配一致，后端仍使用现有原生实现。更改后重启游戏会话。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_graphics_entry.h"]),
        ConfigOption(key: "f6-compute-open", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "F6 计算编码器状态的开发诊断计数，相关实现见 f6_begin 与 f6-rar。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "f6-rar", title: "实验：栅栏链模式 6 忽略读到读屏障", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "默认关闭，仅适用于 fence-chain = 6。开启后，纯读状态之间的 ResourceBarrier（或拆分屏障的前半段）不再让后续 GPU 通道等待所有早期通道，也不结束重叠渲染通道。D3D12 本身不要求此排序；依赖该行为的游戏可能闪烁。每次游戏启动时读取，[perf] f6-rar 会统计相关屏障。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "fence-chain", title: "D3D12 栅栏链模式", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "D3D12 栅栏链模式。ml1114 恢复模式 2；ml1110 至 ml1113 曾将模式 2 限制为模式 1。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c", "app/Madeira/FPSOverlay.swift"]),
        ConfigOption(key: "fence-strict", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "栅栏诊断：1 让 Queue::Wait 等待提交并按串行顺序完成批次；2 还同步等待 Signal 和每帧 Present，会显著变慢。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "fullscreen-window", title: "全屏时让游戏窗口覆盖整个屏幕", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "默认关闭。开启后，D3D12 游戏切换全屏时先将窗口移动到屏幕左上角并铺满屏幕，再由游戏设置所选分辨率，与 Windows 行为一致。可解决《荒野大镖客：救赎 2》等仅调整窗口大小的游戏仍停留在 Wine 桌面旁的问题。每次会话读取。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "gpu-fault-info", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "记录 GPU 命令缓冲区的编码器执行状态；失败时按标签报告故障编码器。首次故障后为全部编码器添加标签以辅助定位。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "gpu-fault-skip", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "gpu-sync", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "GPU 同步诊断：每次 ExecuteCommandLists 提交后等待 GPU 完成，完全取消 CPU/GPU 重叠执行，速度会明显下降。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "gs-null-fragment", title: "为无像素着色器的管线提供空片元函数", kind: .bool, defaultValue: "1", category: "Direct3D 12", note: "默认开启。对启用光栅化但没有像素着色器的网格管线，提供不写入渲染目标的空片元函数，保持深度和模板功能，避免 Metal 中止。设为 0 时拒绝此类管线并丢弃几何着色器。已有像素着色器的管线不受影响。每次会话读取。", choices: [], sources: ["dxmt/src/winemetal/unix/winemetal_unix.c"]),
        ConfigOption(key: "heap-backing", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "堆后备内存开发选项（上游标记 ml1145）。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "ind-count", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "间接绘制统计：从 GPU 回读每条管线的实例数与线程组总数，记录 N 帧；设为 1 表示 3000 帧，并标记单帧下降。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "ind-count-from", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "ind-count 统计开始记录的第一个呈现帧编号。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "ind-probe", title: "ExecuteIndirect 探测（诊断）", kind: .bool, defaultValue: "1", category: "Direct3D 12", note: "默认开启。每条管线每 3 秒通过小型计算通道回读 ExecuteIndirect 的首条参数记录，并记录 [probe] 日志，最多 1500 行。每次探测会结束当前渲染通道。设为 0 可关闭探测。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "indirect-fast", title: "编码 ExecuteIndirect 记录时跳过逐条初始化", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "默认关闭。开启后，ExecuteIndirect 首条记录之后的记录每 64 条批量编码，仅更新偏移并执行间接绘制/分派，避免重复完整初始化。适用于每帧提交大量间接记录的游戏。支持 DXIL 和 DXBC；曲面细分、几何阶段、诊断和截帧仍使用逐条路径。每次会话读取。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "metalfx-upscale", title: "MetalFX 放大倍率", kind: .choice, defaultValue: "", category: "Direct3D 12", note: "使用 Apple MetalFX 空间缩放器放大呈现画面，支持 Direct3D 11 和 12。通常在“游戏详情”>“显示”中为单个游戏设置。", choices: [("", "关闭"), ("1.5", "1.5x"), ("2", "2x")], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c", "app/Madeira/ContentView.swift"]),
        ConfigOption(key: "msc-bounds-check", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "设为 0 时，关闭转换器的 D3D12 稳健缓冲区访问边界检查，相当于 MADEIRA_IR_NO_BOUNDS_CHECK=1。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c", "madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "msc-fail-memo", title: "在当前会话中记住被拒绝的着色器", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "默认关闭。开启后，转换器拒绝过的着色器，在本次游戏运行中不会因另一管线使用相同字节码、根签名和选项而再次转换，可避免大量重复失败。游戏退出后清除记录。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "msc-position-inf-nan", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "位置计算中 Inf/NaN 的转换器兼容性选项，实现位于 madeira_ir_unix.mm（上游构建 217）。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c", "madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "msc-position-invariance", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "转换器的位置不变性选项，具体实现与其他 MSC 兼容性开关位于 madeira_ir_unix.mm。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c", "madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "msc-sample-nan-zero", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "采样结果为 NaN 时的归零兼容性选项，实现位于 madeira_ir_unix.mm（上游构建 217）。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c", "madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "msc-sampler-lod-bias", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "Metal Shader Converter 的采样器 LOD 偏移兼容性选项。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c", "madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "msc-strict-nan", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "Metal Shader Converter 的严格 NaN 处理兼容性选项。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c", "madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "msc-unbounded-retry", title: "为无界范围指定大小后重试被拒绝的着色器", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "默认关闭。开启后，因代码 4（资源不在根签名中）被拒绝的 DXIL 着色器，会在为根签名无界描述符范围指定大小后重试一次：采样器 2048，其他资源 1000000。同一根签名一旦成功，后续着色器优先使用有界范围。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "occlusion-visible", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "遮挡可见性开发选项（上游标记 ml1103）。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "perf-log", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "每 5 秒记录一次 GPU 忙碌时间、CPU 等待回收时间与呈现次数，用于分析帧耗时。设为 0 关闭。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "present-min-ms", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "呈现节奏诊断：让 Present 休眠，保证两帧至少间隔 N 毫秒；例如 200 毫秒约为 5 FPS。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "pso-first-use", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "管线首次使用诊断：记录每条管线首次绑定时的情况，以及它被创建时的呈现帧编号。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "pso-lazy", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "延迟创建管线，默认 1；具体实现见 mad_pso_realize。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "pso-lazy-libs", title: "仅为正在使用的管线创建着色器库", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "默认关闭。开启后，延迟至首次绘制或分派才构建的管线，会在游戏创建管线后释放已转换的 Metal 库，并在首次使用时从着色器缓存重新读取，减少未使用管线占用的内存。需要着色器缓存（默认开启）；使用 pso-warm 时，库会保留至预热编译完成。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "pso-parallel", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "并行创建同一批次所需的新管线，默认 1。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "pso-placeholder", title: "为着色器转换失败的管线提供占位项", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "默认关闭。开启后，顶点或像素着色器转换失败的图形管线会作为占位管线返回，跳过它的绘制，而不直接报告失败。可避免部分游戏收到失败后立即退出。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "pso-share-libs", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "相同的转换后着色器共享一个 MTLLibrary，默认 1。设为 0 则每条管线分别持有库，用于比较内存使用。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "queue-trace", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "队列跟踪：记录前 N 次 ExecuteCommandLists、Signal 和 Wait 的线程、队列类型与栅栏状态；设为 1 表示 400 次。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "quiet-log", title: "降低 Direct3D 12 日志开销（关闭统计帧）", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "默认关闭。开启后，D3D12 日志绕过开销较高的 OutputDebugString，仅通过 Wine 调试输出和 stderr 记录；关闭呈现次数 1500–3000 之间的统计帧及列表 12000–12400 的绘制转储；着色器运行时转换日志只保留前 64 条及之后每 1000 条一次。手动截帧仍可使用。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "readback-far", title: "实验：清空剔除回读", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "默认关闭，仅用于实验。开启后不复制特定深度金字塔回读（至少 4 个 mip 的纹理、mip ≥ 1、R32_FLOAT、最大 64×64），而由 CPU 填入 4096，使依赖它进行 CPU 剔除的游戏绘制全部内容，可能更慢。每次游戏启动时读取。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "readback-swap", title: "使用文件后备内存存放 D3D12 回读缓冲区", kind: .bool, defaultValue: "1", category: "Direct3D 12", note: "默认开启，将至少 8 MB 的 READBACK 缓冲区放在文件后备存储上以降低内存占用。设为 0 使用 Metal 自身内存，使 GPU 写入直接到达 CPU。UPLOAD 缓冲区仍由 upload-swap 控制。每次游戏启动时读取。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "replay-split", title: "记录 Direct3D 12 提交耗时分布", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "默认关闭，仅记录日志。开启后每 5 秒输出 [perf] replay split，将每帧 ExecuteCommandLists 耗时拆分为队列等待、准备、命令缓冲区创建、各类命令及列表结束，用于排查 GPU 不忙但帧率低的问题。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "ring-share", title: "在命令列表之间共享参数缓冲区", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "默认关闭。开启后，GPU 使用完命令列表的参数缓冲块便立即归还，所有列表共用一个池，不再等待列表重新录制才归还。《荒野大镖客：救赎 2》曾在关闭时保留约 1.5 GB 参数缓冲。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "rp-carry", title: "实验：将渲染通道延续至下一个命令列表", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "默认关闭。开启后，同次提交的相邻命令列表如果连续绘制相同目标，中间只有状态设置，则保持渲染通道打开，避免目标写回和重新读取。第二个列表将不再等待整个前一通道；D3D12 不保证该等待，但部分游戏可能依赖它。每次游戏启动时读取，[perf] gpu-traffic 显示节省量。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "rp-discard", title: "实验：DiscardResource 前不存储、后不加载", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "默认关闭。开启后，DiscardResource 丢弃整个目标后，下次通道不再读取旧内容；若通道目标随后在同次提交中被丢弃或完整清除且没有其他使用，则不写回。如果游戏仍读取已丢弃数据，可能出现异常画面。每次游戏启动时读取，[perf] gpu-traffic 显示数据量。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "rp-lean", title: "渲染通道仅填充使用中的目标", kind: .bool, defaultValue: "1", category: "Direct3D 12", note: "默认开启。Metal 渲染通道仅填写实际使用的颜色目标，省去为每个通道填满 8 个槽位的调用和分配；没有纹理的槽位本就被 Metal 忽略，因此结果不变。也适用于 DXMT 的 D3D9/10/11。设为 0 恢复填写全部槽位。每次游戏启动时读取。", choices: [], sources: ["dxmt/src/winemetal/unix/winemetal_unix.c"]),
        ConfigOption(key: "sampler-census", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "采样器统计：每种不同的过滤值及其 Metal 映射只记录一次。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "shader-cache", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "shader-cache-native", title: "原生读取 D3D12 着色器缓存文件", kind: .bool, defaultValue: "1", category: "Direct3D 12", note: "默认开启，由 Madeira 直接读写 AppData\\Local\\Madeira\\ShaderCache 中的 D3D12 着色器缓存，避免每个条目多次经过 Wine 服务端。设为 0 使用 Wine 文件调用。两种方式使用相同文件，游戏创建首条管线时读取。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "skin-check", title: "诊断：检查 GPU 蒙皮网格", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "默认 0，关闭。设为 N 时，以 N 帧为一个诊断窗口（1 表示 8 帧），记录读取计算着色器写入顶点缓冲区的绘制、写入分派与绑定、绘制前最多 32 KB 的数据流摘要及着色器字节码。用于排查角色缺面或尖刺，会增加这些帧的耗时。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "skin-check-capture", title: "诊断：skin-check 复制数据流", kind: .bool, defaultValue: "1", category: "Direct3D 12", note: "启用 skin-check 时默认开启。设为 0 仅记录日志，不在蒙皮分派与绘制之间插入 GPU 复制，便于比较对画面的影响。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "skin-check-every", title: "诊断：skin-check 窗口之间的呈现次数", kind: .int, defaultValue: "300", category: "Direct3D 12", note: "启用 skin-check 后，相邻诊断窗口起点之间的呈现次数，至少 30 次。首个窗口在首次相关绘制后 60 次呈现时开始。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "skin-check-trace", title: "诊断：skin-check 跟踪完整帧", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "默认关闭。与 skin-check 一起开启后，在前两个窗口的首帧逐条记录所有绘制的着色器、数量、数据流和输入布局。带整数顶点输入的管线还记录顶点阶段绑定、CPU 输入副本、首批顶点和字节码，最多 32 次绘制。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "skin-dump", title: "诊断：skin-check 导出蒙皮数据", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "默认关闭。与 skin-check 一起开启后，在首个窗口前两帧完整复制蒙皮计算着色器的输入和输出流，每项最多 256 KB，并以 base64 写入日志，总计最多 4 MB，供电脑重算蒙皮。会使用 24 MB 截取缓冲区。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "skip-ps", title: "", kind: .text, defaultValue: "", category: "Direct3D 12", note: "着色器诊断：跳过指定入口名称的绘制。多个名称以逗号分隔，必须精确匹配。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "skip-ps-cycle", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "轮流应用 skip-ps，每个着色器名称持续 N 秒；设为 0 时同时跳过全部指定名称。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "static-cbv", title: "使用记录绘制时的常量缓冲区", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "默认 0，GPU 执行时读取描述符。1：记录绘制或分派时读取描述符表中的单常量缓冲区范围，避免游戏稍后改写造成常量串用，但 VOLATILE 范围仍保持原行为。2：也固定 VOLATILE 范围。3：只统计改写并输出 [static-cbv] 日志。每次游戏启动时读取。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "typed-uav-atomic", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "实验性修复：为 R32 UAV 纹理缓冲区视图（RWBuffer<uint> 与 UAV 计数器）启用 ShaderAtomic 用途。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "typed-view-align", title: "类型化缓冲区视图对齐", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "默认 0，按 64 字节对齐。16 或 256：按对应边界对齐，且不低于 Metal 对格式的最低要求。4：对首次 GPU 探测确认可用的元素大小，精确从首元素起始，其余使用 16 字节；Metal 拒绝时依次回退为 16、64 字节。每次游戏启动时读取。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "typed-view-shadow", title: "为带偏移的类型化视图创建对齐副本", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "默认关闭。开启后，首元素不在 16 字节边界上的 UPLOAD 类型化 SRV 会读取对齐副本；副本创建于视图建立时，并在每次 ExecuteCommandLists 时刷新。用于处理 GPU 向下对齐与转换器忽略元素偏移的问题。view-census 会统计副本，每次游戏启动时读取。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "upload-guard", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "上传堆诊断：1 记录 GPU 仍在使用但已被游戏重写的数据；2 还与 GPU 实际读取的内容比较。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "upload-guard-bytes", title: "", kind: .int, defaultValue: "256", category: "Direct3D 12", note: "upload-guard 对每段内存计算哈希的字节数，范围 16～4096。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "upload-swap", title: "使用文件后备内存存放 D3D12 上传缓冲区", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "D3D12 上传缓冲区的文件后备内存开关，madeira.cfg 中的 upload-swap，默认 1（开启）。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "use-dedup", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "绘制命令链完成编码后才提交资源使用声明；提前返回的绘制不会提交，下一次开始时丢弃这些声明。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "view-census", title: "诊断：报告使用回退路径的缓冲区视图", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "默认关闭。开启后统计并记录无法转换为 Metal 纹理缓冲区的类型化视图、被资源末尾截短或越界的视图/常量缓冲区视图，以及各像素格式的最低对齐要求。不改变其他行为。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "vis-trace", title: "诊断：逐帧绘制和剔除回读", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "默认关闭。开启后每次呈现记录绘制、深度通道、多目标、索引、分派、深度金字塔回读、偏移视图和队列等待统计，并记录剔除所用金字塔 22×10、11×5、5×2 mip 的全部值。GPU 还将 mip 复制到 Madeira 内存，对回读中的旧帧数据标记 STALE。每次游戏启动时读取。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "vsps-fill", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "顶点与像素着色器填充路径的转换器兼容性选项。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c", "madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "env.DXMT_AIRCONV_DUMP", title: "", kind: .text, defaultValue: "", category: "Direct3D 9/10/11（DXMT）", note: "将 DXMT_AIRCONV_DUMP 设为目录后，每次 DXSOCompile 都会导出 {kind}_{hash}.metallib。可用 xcrun air-objdump 反汇编，仅用于问题排查。", choices: [], sources: ["dxmt/src/airconv/dxso_compile.cpp", "dxmt/src/d3d9/d3d9_shader.cpp"]),
        ConfigOption(key: "env.DXMT_API_CENSUS", title: "", kind: .text, defaultValue: "", category: "Direct3D 9/10/11（DXMT）", note: "", choices: [], sources: ["dxmt/src/winemetal/wmt_api_census.c"]),
        ConfigOption(key: "env.DXMT_CACHE_STATS", title: "", kind: .text, defaultValue: "", category: "Direct3D 9/10/11（DXMT）", note: "设为 1 启用 DXMT 缓存命中与未命中次数日志。", choices: [], sources: ["dxmt/src/winemetal/unix/cache.c"]),
        ConfigOption(key: "env.DXMT_CAPTURE_EXECUTABLE", title: "", kind: .text, defaultValue: "", category: "Direct3D 9/10/11（DXMT）", note: "", choices: [], sources: ["dxmt/src/dxmt/dxmt_capture.cpp"]),
        ConfigOption(key: "env.DXMT_CAPTURE_FRAME", title: "", kind: .text, defaultValue: "", category: "Direct3D 9/10/11（DXMT）", note: "", choices: [], sources: ["dxmt/src/dxmt/dxmt_command_queue.cpp"]),
        ConfigOption(key: "env.DXMT_CENSUS_THROTTLE", title: "", kind: .bool, defaultValue: "32-bit only", category: "Direct3D 9/10/11（DXMT）", note: "按实际经过的时间限制统计日志频率，同时保证进程首次报告总会输出，便于诊断启动后很快退出的程序。", choices: [], sources: ["dxmt/src/dxmt/dxmt_mem_census.cpp"]),
        ConfigOption(key: "env.DXMT_CLEAR_DISCARD_STORE", title: "", kind: .bool, defaultValue: "32-bit only", category: "Direct3D 9/10/11（DXMT）", note: "控制清除后丢弃存储的优化，仅 i386 构建默认开启。", choices: [], sources: ["dxmt/src/dxmt/dxmt_context.cpp"]),
        ConfigOption(key: "env.DXMT_CMD_CENSUS", title: "", kind: .text, defaultValue: "", category: "Direct3D 9/10/11（DXMT）", note: "", choices: [], sources: ["dxmt/src/winemetal/unix/winemetal_unix.c"]),
        ConfigOption(key: "env.DXMT_CONFIG", title: "", kind: .text, defaultValue: "", category: "Direct3D 9/10/11（DXMT）", note: "加载 DXMT_CONFIG_FILE 指定的文件，或当前工作目录下的 dxmt.conf。", choices: [], sources: ["dxmt/src/util/config/config.cpp"]),
        ConfigOption(key: "env.DXMT_CONFIG_FILE", title: "", kind: .text, defaultValue: "", category: "Direct3D 9/10/11（DXMT）", note: "指定 DXMT 配置文件路径；未指定时读取当前工作目录下的 dxmt.conf。", choices: [], sources: ["dxmt/src/util/config/config.cpp"]),
        ConfigOption(key: "env.DXMT_D9_ANISO_LIMIT", title: "", kind: .text, defaultValue: "", category: "Direct3D 9/10/11（DXMT）", note: "D3D9 各向异性过滤限制。相关资源只由编码线程写入，可结合 DXMT_DEBUG 检查单写入线程约束。", choices: [], sources: ["dxmt/src/d3d9/d3d9_device.cpp"]),
        ConfigOption(key: "env.DXMT_D9_BATCH_READBACK", title: "", kind: .text, defaultValue: "", category: "Direct3D 9/10/11（DXMT）", note: "", choices: [], sources: ["dxmt/src/d3d9/d3d9_device.cpp"]),
        ConfigOption(key: "env.DXMT_D9_BINDING_PRUNE", title: "", kind: .text, defaultValue: "", category: "Direct3D 9/10/11（DXMT）", note: "仅处理编译器实际使用的采样阶段，避免为无效绑定查询采样器缓存、创建纹理视图和保留资源；固定功能组合器保留原路径。", choices: [], sources: ["dxmt/src/d3d9/d3d9_device.cpp"]),
        ConfigOption(key: "env.DXMT_D9_CANONICAL_BLEND", title: "", kind: .text, defaultValue: "", category: "Direct3D 9/10/11（DXMT）", note: "关闭混合时忽略六个混合操作与因子字段，在哈希和冲突检查前统一这些值，使等价配置共享同一个 Metal 管线。", choices: [], sources: ["dxmt/src/d3d9/d3d9_device.cpp"]),
        ConfigOption(key: "env.DXMT_D9_EXTENTLOG", title: "", kind: .text, defaultValue: "", category: "Direct3D 9/10/11（DXMT）", note: "D3D9 呈现尺寸诊断，记录后缓冲区与目标区域的尺寸，用于排查图像边缘缺失等缩放问题。", choices: [], sources: ["dxmt/src/d3d9/d3d9_debug.hpp"]),
        ConfigOption(key: "env.DXMT_D9_LOCKLOG", title: "", kind: .text, defaultValue: "", category: "Direct3D 9/10/11（DXMT）", note: "D3D9 纹理锁定诊断，区分 managed、普通锁定与 SYSTEMMEM 更新路径，并按资源属性去重记录。", choices: [], sources: ["dxmt/src/d3d9/d3d9_surface.cpp"]),
        ConfigOption(key: "env.DXMT_D9_NODIRTY_SWEEP", title: "", kind: .text, defaultValue: "", category: "Direct3D 9/10/11（DXMT）", note: "D3D9 纹理脏区处理。原先 GPU 副本会一直保留最后收到的内容，只有显式 AddDirtyRect 或 EvictManagedResources 才会更新，因此写入、绘制后再原地改写的纹理可能仍显示初始内容。", choices: [], sources: ["dxmt/src/d3d9/d3d9_texture.cpp"]),
        ConfigOption(key: "env.DXMT_D9_PIPELINE_STATS", title: "", kind: .text, defaultValue: "", category: "Direct3D 9/10/11（DXMT）", note: "D3D9 管线编译诊断。参考实现会在绘制位置同步编译冷管线，例如 wined3d、DXVK 默认路径和 D3D11 的阻塞 GetPipeline；异步分支跳过绘制属于不同处理方式。", choices: [], sources: ["dxmt/src/d3d9/d3d9_device.cpp"]),
        ConfigOption(key: "env.DXMT_D9_QUERY_ADAPTIVE", title: "", kind: .text, defaultValue: "", category: "Direct3D 9/10/11（DXMT）", note: "仅针对紧密轮询施加协作式背压，避免按整个生命周期计数而在第三次检查后惩罚正常异步剔除循环。间隔达到 250 微秒视为新的轮询批次。", choices: [], sources: ["dxmt/src/d3d9/d3d9_query.cpp"]),
        ConfigOption(key: "env.DXMT_D9_READBACK_STATS", title: "", kind: .text, defaultValue: "", category: "Direct3D 9/10/11（DXMT）", note: "", choices: [], sources: ["dxmt/src/d3d9/d3d9_device.cpp"]),
        ConfigOption(key: "env.DXMT_D9_SCENE_BATCH", title: "", kind: .text, defaultValue: "", category: "Direct3D 9/10/11（DXMT）", note: "相关状态仅由编码线程写入：Resolve 分配，commit 封存。可启用 DXMT_DEBUG 的单写入者断言。", choices: [], sources: ["dxmt/src/d3d9/d3d9_device.cpp"]),
        ConfigOption(key: "env.DXMT_D9_SHADER_PRUNE", title: "", kind: .text, defaultValue: "", category: "Direct3D 9/10/11（DXMT）", note: "编译器绑定预扫描与元数据掩码使用相同的采样操作码和槽位辅助函数，包括 SM1 隐式阶段。未读取的槽位不应进入着色器签名或降级转换过程。", choices: [], sources: ["dxmt/src/d3d9/d3d9_shader.cpp"]),
        ConfigOption(key: "env.DXMT_D9_SMALL_MIRROR_CACHE", title: "", kind: .text, defaultValue: "", category: "Direct3D 9/10/11（DXMT）", note: "小型 MANAGED 镜像本身成本低，但重建仍需排空 GPU 队列。保留有界工作集，避免改变 LockRect 可见性或丢弃 CPU 持有的权威数据。", choices: [], sources: ["dxmt/src/d3d9/d3d9_texture.cpp"]),
        ConfigOption(key: "env.DXMT_D9_SUBMIT_STATS", title: "", kind: .text, defaultValue: "", category: "Direct3D 9/10/11（DXMT）", note: "设备锁保证调用者串行执行。记录提交原因而不只统计 GPU 总量，因为上传队列也可独立提交缓冲区。", choices: [], sources: ["dxmt/src/d3d9/d3d9_device.cpp"]),
        ConfigOption(key: "env.DXMT_D9_UPLOAD_COMMIT_MB", title: "", kind: .text, defaultValue: "", category: "Direct3D 9/10/11（DXMT）", note: "", choices: [], sources: ["dxmt/src/d3d9/d3d9_device.cpp"]),
        ConfigOption(key: "env.DXMT_D9_VIRTUAL_MODE", title: "", kind: .text, defaultValue: "", category: "Direct3D 9/10/11（DXMT）", note: "全屏矩形使用窗口所属显示器原点及后备缓冲区尺寸。在 iOS 上，旧的仅无边框处理会让全屏窗口超出较小的虚拟桌面，造成指针范围提前被截断。", choices: [], sources: ["dxmt/src/d3d9/d3d9_device.cpp"]),
        ConfigOption(key: "env.DXMT_DISPLAY_MODE_STATS", title: "", kind: .text, defaultValue: "", category: "Direct3D 9/10/11（DXMT）", note: "显示模式诊断，需显式设置 DXMT_DISPLAY_MODE_STATS=1 启用。", choices: [], sources: ["dxmt/src/dxgi/dxgi_output.cpp"]),
        ConfigOption(key: "env.DXMT_DUMP_D9_LAYOUT", title: "", kind: .text, defaultValue: "", category: "Direct3D 9/10/11（DXMT）", note: "设为 1 后导出不同的 D3D9 顶点布局，检查从 D3DDECLTYPE 到 MTLAttributeFormat 的转换，便于排查手动顶点读取路径中的格式不匹配。", choices: [], sources: ["dxmt/src/d3d9/d3d9_shader.cpp"]),
