        ConfigOption(key: "env.MADEIRA_DNSAPI_UNIXLIB", title: "", kind: .text, defaultValue: "", category: "内存与 JIT 池", note: "默认绑定 dnsapi 的 Unix 实现。设为 0 保留旧存根表，使所有 dnsapi Unix 调用返回 STATUS_NOT_SUPPORTED。", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
