        ConfigOption(key: "env.MADEIRA_FIXED_BASE_GUARD", title: "为固定基址游戏保留 0x140000000", kind: .bool, defaultValue: "0", category: "内存与 JIT 池", note: "默认关闭。开启后，仅用于资源查询的映像不会占据 0x140000000 的可执行预留窗口，为无法重定位的游戏保留该地址。它也会移动其他程序的映像，因此只应写入确有需要的游戏专用配置。会话启动时读取。", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
