        ConfigOption(key: "env.MADEIRA_NO_IMAGE_RETIRE", title: "", kind: .text, defaultValue: "", category: "内存与 JIT 池", note: "映像移交期间释放 virtual_mutex 后，其他线程可能合法占用暂时空出的区域；该情况应报告而不能覆盖。设为 1 完全关闭这种映像移交。", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
