        ConfigOption(key: "env.MADEIRA_PIN_GRAPHICS_DLLS", title: "保持图形 DLL 处于加载状态", kind: .bool, defaultValue: "0", category: "内存与 JIT 池", note: "默认关闭。在 D3D12 设备或探测调用时固定已经加载的 D3D12、DXGI 和 Wine Metal DLL，直到进程正常退出，避免反复卸载和加载副本。DLL 数据保持存活，不回收可执行区域或改变 GPU 能力。更改后重启会话。", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
