        ConfigOption(key: "env.MADEIRA_POOL_BIG_SLOT_MB", title: "", kind: .text, defaultValue: "", category: "内存与 JIT 池", note: "在拆分池空洞旁为单个至少 64 MB 的映像（如 Social Club 的 libcef.dll）保留 N MB。默认关闭。", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_POOL_CODE_EXIT_RECLAIM", title: "回收已退出程序的代码缓冲区", kind: .bool, defaultValue: "1", category: "内存与 JIT 池", note: "默认开启。会话中的程序退出后，其模拟器代码缓冲区归还 JIT 池，等待 3 秒且无线程在其中执行后可复用。设为 0 时仍保留至 Madeira 关闭，连续多次启动退出可能使可用代码缓冲区变小。", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_POOL_HEAD_RESERVE_MB", title: "", kind: .text, defaultValue: "", category: "内存与 JIT 池", note: "在 FEX 池尾预算中为映像保留 48–256 MB 余量。默认 48，保持现有策略。区域 C 不变。", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_POOL_LOW_IMAGES", title: "在空闲代码缓冲区空间中放置小型映像", kind: .bool, defaultValue: "0", category: "内存与 JIT 池", note: "默认关闭。常规 JIT 映像分配失败时，最多 16 MB 的副本可以使用尚未分配的区域 C，并为代码缓冲区保留 4 MB。需要 pool-low，仅适用于 64 位进程。不缩小正在使用的缓冲区或 pool-low-margin。", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
