        ConfigOption(key: "env.MADEIRA_RDR2_VA_HOLD", title: "为荒野大镖客：救赎 2 保留 8960 MB", kind: .bool, defaultValue: "0", category: "内存与 JIT 池", note: "默认关闭，仅在 env.MADEIRA_SC_PA_POOLS = 2 时使用。调整 Social Club 布局 2 的 PartitionAlloc、元数据和 Oilpan 保留区，为 Wine 线程及分配提供更多空间，使 FEX 区域增至 15 GB，并从启动起为《荒野大镖客：救赎 2》的 8960 MB 请求保留 [0x75d0000000, 0x7800000000)。只应用于该游戏；GTA V 继续使用原布局 2。会话启动时读取。", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_RESOURCE_MAP_COPY", title: "", kind: .text, defaultValue: "", category: "内存与 JIT 池", note: "资源映射副本控制，避免版本查询保留额外副本耗尽 JIT 池。virtual_map_section 在映射周围设置标志；带 CLR 头的映像会清除该标志，因为 CoreCLR 的 R2R 程序集会通过这种方式映射并运行。", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
