        ConfigOption(key: "env.MADEIRA_SMALL_STACK_EXES", title: "线程保留 2 MB 栈的程序", kind: .text, defaultValue: "", category: "内存与 JIT 池", note: "默认留空，所有线程栈至少 8 MB，以满足 Chromium。用逗号分隔 exe 名称（如 RDR2.exe），这些程序的线程栈按请求分配但至少 2 MB，以节省共享地址空间。切勿列入 Chromium 程序 SocialClubHelper.exe、Launcher.exe 或 steamwebhelper.exe。线程启动时读取。", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
