        ConfigOption(key: "env.MADEIRA_SWAP_COVERAGE", title: "交换层覆盖范围", kind: .choice, defaultValue: "", category: "内存与 JIT 池", note: "交换层开启时决定文件支持的分配范围。classic（默认）：客户地址区域内单次至少 8 MB 的提交；blocks：所有至少 1 MB 的分配；wide：再包括区域外分配和新预留；broad：为 FEX 区域下方达到 swap-min-mb（默认 4 MB）的新预留提供完整后备，取消提交时打洞。swap-mb 为软磁盘上限。留空时，swap-mode = 2 使用 broad，其他使用 classic。", choices: [("", "大块分配（8 MB 及以上）"), ("blocks", "所有 1 MB 及以上的分配"), ("wide", "1 MB 及以上分配及溢出部分"), ("broad", "完整预留区域（4 MB 及以上，广泛覆盖）")], sources: ["build/ntdll-unix/virtual_ios.c", "app/Madeira/Library.swift"]),
