        ConfigOption(key: "env.MADEIRA_SWAP_RESERVE_MAX_MB", title: "交换层：支持的最大预留区域（MB）", kind: .int, defaultValue: "", category: "内存与 JIT 池", note: "交换层完整支持的新预留区域最大值。wide 默认 256 MB，最多 4 GB；broad 默认 8 GB，最多 16 GB。在 broad（swap-mode = 2）下设为 9216，可支持《荒野大镖客：救赎 2》的 8960 MB 堆。会话启动时读取。", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_THREAD_STACK_SPILL", title: "内存空间不足时允许内核选择新线程地址", kind: .bool, defaultValue: "0", category: "内存与 JIT 池", note: "默认关闭。开启后，从 Wine 管理区域起点而非 4 GB 处查找新线程的 1 MB 内核栈及模拟器栈，减少无效尝试；该区域已满时由内核使用其他空闲地址，避免创建线程失败。会话启动时读取。", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_TOTAL_PHYS_MB", title: "", kind: .text, defaultValue: "", category: "内存与 JIT 池", note: "内存上限由实际测量得出：os_proc_available_memory() 的剩余可用量加上 TASK_VM_INFO.phys_footprint 的已计费占用，得到本进程的有效总额，并在首次使用时缓存。", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
