        ConfigOption(key: "pool", title: "JIT 池大小（MB）", kind: .text, defaultValue: "", category: "内存与 JIT 池", note: "通过 madeira.cfg 的 pool 指定每次启动的 JIT 池大小，单位 MB，范围 256–1152。此设置优先于其他池大小设置。", choices: [], sources: ["app/Madeira/ContentView.swift"]),
        ConfigOption(key: "pool-low", title: "将 JIT 代码缓冲区放在可执行窗口下方", kind: .bool, defaultValue: "0", category: "内存与 JIT 池", note: "默认关闭。设为 1 后，将 0x140000000 可执行窗口下方的连续空闲区扣除 pool-low-margin 后用作第三个调试器区域，供模拟器代码缓冲区使用，让原 JIT 池留给 DLL 副本。需要主池位于窗口上方，并会消耗该区域大小的内存。启动时读取，游戏专用配置优先。", choices: [], sources: ["app/Madeira/StikJITHelper.swift"]),
