        ConfigOption(key: "pool-page-fit", title: "按内存页对齐拆分池区域", kind: .bool, defaultValue: "0", category: "内存与 JIT 池", note: "默认关闭。启用 pool-split 后按 16 KB 内存页而非 16 MB 步长调整区域 A/B，在不增加请求预算的情况下保留小块余量；启用 pool-low 时也按页调整 C，保持 pool-low-margin。额外页面会消耗内存。启动时读取，游戏专用配置优先。更改后重启 Madeira 并重新启用 JIT。", choices: [], sources: ["app/Madeira/StikJITHelper.swift"]),
        ConfigOption(key: "pool-pair", title: "拆分 JIT 池：优先使用窗口上方的两个区域", kind: .bool, defaultValue: "1", category: "内存与 JIT 池", note: "默认开启，需要 pool-split。当最大的空闲区位于无法拆分的可执行窗口下方时，如果窗口上方两个区域合计更大，则优先使用它们；放置失败时回退到单一区域。设为 0 关闭。启动时读取，游戏专用配置优先。", choices: [], sources: ["app/Madeira/StikJITHelper.swift"]),
        ConfigOption(key: "pool-split", title: "围绕主线程栈拆分 JIT 池", kind: .bool, defaultValue: "0", category: "内存与 JIT 池", note: "默认关闭。当主线程栈分割唯一可执行区域，使池小于请求大小（pool 默认 896 MB）时，开启此项可将栈上方空闲区作为第二调试器区域，与第一个区域组成同一池。会增加第二个区域大小的内存占用。启动时读取，游戏专用配置优先。", choices: [], sources: ["app/Madeira/StikJITHelper.swift"]),
        ConfigOption(key: "swap-images", title: "交换层：将纯 x64 DLL 和程序存放到文件", kind: .bool, defaultValue: "0", category: "内存与 JIT 池", note: "默认关闭，需要 swap-mb。开启后，将纯 x64 映像的已读取节移入交换层文件，降低计入内存上限的占用；配合 env.MADEIRA_X64_IMAGE_NOCOPY = 1 使用。与相邻节共享的页边缘仍留在内存。建议写入游戏专用配置，会话启动时读取。", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
