        ConfigOption(key: "env.MADEIRA_PIPE_TRACE_LIMIT", title: "", kind: .text, defaultValue: "", category: "Wine 核心（ntdll）", note: "管道跟踪日志输出上限，用于控制诊断输出。", choices: [], sources: ["wine/dlls/ntdll/unix/file.c"]),
        ConfigOption(key: "env.MADEIRA_POWER_GOV_BAND_MJ", title: "", kind: .text, defaultValue: "", category: "Wine 核心（ntdll）", note: "功耗调节器在切换节能模式前允许累计能量偏差的范围，单位为毫焦耳，默认 1000。", choices: [], sources: ["build/ntdll-unix/server_ios.c"]),
        ConfigOption(key: "env.MADEIRA_POWER_GOV_MW", title: "", kind: .text, defaultValue: "", category: "Wine 核心（ntdll）", note: "游戏提交画面期间的进程 CPU 功率目标，单位为毫瓦；未设置或 0 表示关闭。", choices: [], sources: ["build/ntdll-unix/server_ios.c"]),
        ConfigOption(key: "env.MADEIRA_QUIET", title: "", kind: .text, defaultValue: "", category: "Wine 核心（ntdll）", note: "运行时静默选项，用于控制诊断输出。", choices: [], sources: ["build/ntdll-unix/server_ios.c", "dxmt/src/winemetal/unix/winemetal_unix.c", "app/Madeira/Winios/Winios.m"]),
        ConfigOption(key: "env.MADEIRA_RTCS_LOG", title: "", kind: .text, defaultValue: "", category: "Wine 核心（ntdll）", note: "控制 [rtcs] pre 日志：all 记录全部，数字 N 表示每线程每秒最多 N 条；默认 10，0 表示不记录。", choices: [], sources: ["build/ntdll-unix/loader_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SC_CEF", title: "在单进程中运行 Social Club 的 Chromium", kind: .bool, defaultValue: "1", category: "Wine 核心（ntdll）", note: "默认开启，0 关闭。SocialClubHelper.exe 使用 --single-process，关闭 PartitionAllocBackupRefPtr，并为 V8 启用 --jitless（MADEIRA_JITLESS = 0 可保留 JIT）；拒绝其 --type= 子进程。已加载 socialclub.dll 的非助手进程不再为 libcef.dll 创建 JIT 池副本。未使用 Social Club 的程序不受影响。", choices: [], sources: ["build/ntdll-unix/process_ios.c", "build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SC_CEF_FLAGS", title: "SocialClubHelper.exe 额外启动参数", kind: .text, defaultValue: "", category: "Wine 核心（ntdll）", note: "在 env.MADEIRA_SC_CEF 开启时，原样追加到 SocialClubHelper.exe 命令行，例如 --disable-gpu 或 --enable-logging=file --v=1。若含 --js-flags=，会在其中首先加入 --jitless，除非 MADEIRA_JITLESS = 0。", choices: [], sources: ["build/ntdll-unix/process_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SECTION_PROCESS_LIMIT", title: "", kind: .text, defaultValue: "", category: "Wine 核心（ntdll）", note: "按当前进程确定节映射的地址空间限制，避免 32 位访客启动后遗留的共享上限被错误应用到后续原生辅助进程。", choices: [], sources: ["build/ntdll-unix/env_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SOCK_WIRE", title: "", kind: .text, defaultValue: "", category: "Wine 核心（ntdll）", note: "套接字收发诊断。每次记录会增加 getpeername 调用开销，可能影响 Steam 连接的时间预算；既有分类规则也不适合直接判断 TLS 1.3 加密数据。", choices: [], sources: ["wine/dlls/ntdll/unix/socket.c"]),
        ConfigOption(key: "env.MADEIRA_SPAWN_BLOCK", title: "", kind: .text, defaultValue: "", category: "Wine 核心（ntdll）", note: "按游戏指定不启动的可选辅助进程，以减少各 x64 伪进程复制系统 DLL 和分配独立代码缓冲区的内存开销。", choices: [], sources: ["build/ntdll-unix/process_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SRV_FGETPATH", title: "通过一次调用获取已打开文件的名称（服务端）", kind: .bool, defaultValue: "0", category: "Wine 核心（ntdll）", note: "默认关闭，使用 realpath。开启后，Wine 服务端通过文件描述符的 fcntl F_GETPATH 获取刚打开文件的路径，避免逐层检查目录；失败仍回退到 realpath。适合频繁打开文件的游戏。每次启动读取，后续游戏不会继承前一个游戏的设置。", choices: [], sources: ["app/Madeira/WineProcessBridge.m", "build/wineserver/fd_ios.c"]),
        ConfigOption(key: "env.MADEIRA_DNS_TIMEOUT_MS", title: "", kind: .text, defaultValue: "", category: "Wine 库", note: "DNS 查询超时设置，单位为毫秒。", choices: [], sources: ["wine/dlls/ws2_32/unixlib.c"]),
        ConfigOption(key: "env.MADEIRA_MFC", title: "Microsoft MFC（mfc140.dll、mfc140u.dll）", kind: .bool, defaultValue: "1", category: "Wine 库", note: "默认开启。将微软 VC++ 包中的 MFC（mfc140.dll、mfc140u.dll）链接到游戏的 system32；Wine 本身没有 MFC，依赖它的游戏缺少时会立即停止。设为 0 不包含 MFC，会话启动时读取。", choices: [], sources: ["app/Madeira/WineProcessBridge.m"]),
        ConfigOption(key: "env.MADEIRA_MONO_DEFAULTS", title: "", kind: .text, defaultValue: "", category: "Wine 库", note: "加载 32 位或 64 位 Wine Mono 前默认设置 MONO_THREADS_SUSPEND=coop，并向 MONO_DEBUG 添加 keep-delegates；已有设置优先，读取后恢复旧值。设为 0 时不添加默认值。", choices: [], sources: ["wine/dlls/mscoree/metahost.c"]),
        ConfigOption(key: "env.MADEIRA_NSI_DEVICE_CACHE", title: "", kind: .text, defaultValue: "", category: "Wine 库", note: "默认开启；无法打开 \\\\.\\Nsi 时缓存失败结果，避免每次调用都重试。设为 0 时每次重试。", choices: [], sources: ["wine/dlls/nsi/nsi.c"]),
        ConfigOption(key: "env.MADEIRA_NSI_NOTIFY_PENDING", title: "", kind: .text, defaultValue: "", category: "Wine 库", note: "默认开启；缺少 \\\\.\\Nsi 时，地址变更请求保持等待，而非立即失败。设为 0 时恢复立即失败的行为。", choices: [], sources: ["wine/dlls/nsi/nsi.c"]),
        ConfigOption(key: "env.MADEIRA_CLIP_NOTIFY_ALWAYS", title: "", kind: .text, defaultValue: "", category: "Wine 服务端", note: "设为 1 时，每次 ClipCursor 调用都通知前台线程，保持旧行为。", choices: [], sources: ["build/wineserver/queue_ios.c"]),
        ConfigOption(key: "env.MADEIRA_CTX_FRAME", title: "", kind: .text, defaultValue: "", category: "Wine 服务端", note: "线程上下文诊断使用系统调用栈帧范围判断当前上下文，避免仅凭原生程序计数器是否属于 ARM64EC 而误判 FEX JIT 代码。", choices: [], sources: ["build/wineserver/mach_ios.c"]),
        ConfigOption(key: "env.MADEIRA_DEAD_RELEASE", title: "", kind: .text, defaultValue: "", category: "Wine 服务端", note: "控制已结束对象释放路径；环境值仅读取一次，避免每次释放都调用 getenv。", choices: [], sources: ["wine/server/object.c"]),
        ConfigOption(key: "env.MADEIRA_REAL_SUSPEND", title: "", kind: .text, defaultValue: "", category: "Wine 服务端", note: "设为 1 时允许真实挂起线程，默认关闭。所有伪进程和 wineserver 共处同一 Mach 进程，挂起持有共享分配器或代码失效锁的线程可能阻塞其他线程。", choices: [], sources: ["build/wineserver/mach_ios.c"]),
        ConfigOption(key: "env.MADEIRA_REPLACE_READONLY_LINK", title: "", kind: .text, defaultValue: "", category: "Wine 服务端", note: "默认开启：通过链接覆盖只读文件时，以新文件替换链接。设为 0 时返回拒绝访问。", choices: [], sources: ["build/wineserver/fd_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SRV_DIRECT", title: "在调用线程中执行简单服务端请求", kind: .text, defaultValue: "0", category: "Wine 服务端", note: "默认关闭。1：简单 Wine 服务端请求（文件、描述符、句柄、映射、注册表、事件、信号量、互斥量和完成端口）在持有服务端锁的调用线程上执行，减少管道往返和线程切换。2：再包括等待 select、定时器和 set_cursor。其余请求仍通过管道。每次启动读取。", choices: [("", "关闭（默认）"), ("1", "文件、句柄、注册表、事件、信号量"), ("2", "还包括等待、定时器和光标")], sources: ["build/wineserver/request_ios.c", "build/wineserver/fd_ios.c", "build/ntdll-unix/server_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SRV_DOORBELL", title: "", kind: .text, defaultValue: "", category: "Wine 服务端", note: "设为 0 时，每轮都读取所有客户端文件描述符，保持旧行为。", choices: [], sources: ["build/wineserver/fd_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SRV_ECO_FOLLOW", title: "服务端线程跟随节能模式", kind: .bool, defaultValue: "0", category: "Wine 服务端", note: "默认关闭。开启后，节能模式打开时，Wine 服务端线程从 user-interactive 降为 utility QoS，随游戏线程转到能效核心，关闭节能模式时恢复。服务端请求可能变慢。每次启动读取。", choices: [], sources: ["build/wineserver/fd_ios.c", "app/Madeira/WineProcessBridge.m"]),
        ConfigOption(key: "env.MADEIRA_SRV_FD_SOCKET", title: "通过进程套接字传递文件描述符", kind: .bool, defaultValue: "0", category: "Wine 服务端", note: "默认 0，通过 get_handle_fd 回复直接返回服务端复制的文件描述符，省去 sendmsg、recvmsg、fcntl 和相应日志。设为 1 恢复通过进程套接字传递。每次应用运行读取一次。", choices: [], sources: ["build/ntdll-unix/server_ios.c", "build/wineserver/fd_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SRV_FULLSCAN_MS", title: "", kind: .text, defaultValue: "", category: "Wine 服务端", note: "启用门铃唤醒时，完整读取所有客户端文件描述符的间隔，默认 10 毫秒。", choices: [], sources: ["build/wineserver/fd_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SRV_IDLE_US", title: "服务端循环最长休眠时间（微秒）", kind: .int, defaultValue: "1000", category: "Wine 服务端", note: "默认 1000 微秒（1 毫秒），范围 100–50000。请求和定时器仍立即唤醒 Wine 服务端，只有套接字轮询和描述符扫描等待该周期。值越大，空闲唤醒越少，但网络套接字和管道就绪响应更慢。主要配合 env.MADEIRA_SRV_DIRECT 使用，每次启动读取。", choices: [], sources: ["build/wineserver/fd_ios.c", "app/Madeira/WineProcessBridge.m"]),
        ConfigOption(key: "env.MADEIRA_SRV_LOG_ALL", title: "输出所有按描述符记录的服务端日志", kind: .bool, defaultValue: "0", category: "Wine 服务端", note: "默认 0，Wine 服务端的 add_poll_user 和 send_client_fd 日志只保留前 64 条及之后每 1000 条一次，发送失败始终记录。设为 1 恢复记录每一条。每次启动读取。", choices: [], sources: ["build/wineserver/fd_ios.c", "build/wineserver/request_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SRV_NOSEM", title: "", kind: .text, defaultValue: "", category: "Wine 服务端", note: "控制服务端等待是否使用信号量，用于避免信号量计时等待立即返回、循环不再休眠的情况；不改变原有休眠时间计算。", choices: [], sources: ["build/wineserver/fd_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SRV_POLL_US", title: "", kind: .text, defaultValue: "", category: "Wine 服务端", note: "启用门铃唤醒时，套接字轮询和文件描述符扫描的间隔，默认 1000 微秒；0 表示每轮执行。", choices: [], sources: ["build/wineserver/fd_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SRV_WAKE_COALESCE", title: "", kind: .text, defaultValue: "", category: "Wine 服务端", note: "设为 0 时，每个请求分别发送一次唤醒信号，保持旧行为。", choices: [], sources: ["build/wineserver/fd_ios.c"]),
        ConfigOption(key: "env.MADEIRA_STORAGE_DEVICE", title: "", kind: .text, defaultValue: "", category: "Wine 服务端", note: "设为 0 时不提供 \\\\.\\PhysicalDrive0，即 Wine 环境磁盘容量设备。", choices: [], sources: ["build/wineserver/storage_device_ios.c"]),
        ConfigOption(key: "env.MADEIRA_STUCK_WAIT_SECS", title: "", kind: .text, defaultValue: "", category: "Wine 服务端", note: "等待超过多少秒后记录卡住的线程诊断，默认 5 秒，最小 1 秒。", choices: [], sources: ["build/wineserver/queue_ios.c"]),
        ConfigOption(key: "env.MADEIRA_TIMER_FAIRNESS", title: "窗口持续重绘时仍运行定时器", kind: .bool, defaultValue: "1", category: "Wine 服务端", note: "默认开启。窗口持续使自己重绘时，等待超过 100 毫秒的定时器会优先于绘制消息，避免定时器长期无法执行，例如安装器停在“准备安装”。设为 0 恢复严格消息顺序。每次应用运行读取一次。", choices: [], sources: ["build/wineserver/queue_ios.c"]),
        ConfigOption(key: "env.MADEIRA_USD_TIME", title: "", kind: .text, defaultValue: "", category: "Wine 服务端", note: "更新共享用户数据中的时间，避免时间页冻结导致访客程序的超时判断和登录后延迟检查永远无法触发。", choices: [], sources: ["build/wineserver/fd_ios.c"]),
        ConfigOption(key: "no-local-read", title: "", kind: .bool, defaultValue: "0", category: "Wine 服务端", note: "设为 1 时禁用本地读取优化，用于运行时诊断与兼容性比较。", choices: [], sources: ["build/wineserver/mach_ios.c"]),
        ConfigOption(key: "env.MADEIRA_ARENA_TEST", title: "", kind: .text, defaultValue: "", category: "x86 模拟（FEX）", note: "启用 FEX 内存分配区域自检，用于高级诊断。", choices: [], sources: ["FEX/Source/Windows/Common/ArenaSelfTest.cpp"]),
        ConfigOption(key: "env.MADEIRA_FEX_AVX", title: "", kind: .text, defaultValue: "", category: "x86 模拟（FEX）", note: "默认关闭 AVX/AVX2，让检测 CPUID 的游戏使用 SSE 路径。设为 1 时，FEX 通过 128 位模拟支持必须使用 AVX 的游戏，但运行开销更高。", choices: [], sources: ["FEX/Source/Windows/Common/CPUFeatures.cpp"]),
        ConfigOption(key: "env.MADEIRA_FEX_BRANCH_HISTORY", title: "", kind: .text, defaultValue: "", category: "x86 模拟（FEX）", note: "仅为指定可执行文件启用分支历史记录，并在创建上下文和 JIT 前生效。", choices: [], sources: ["FEX/Source/Windows/ARM64EC/Module.cpp"]),
        ConfigOption(key: "env.MADEIRA_FEX_CALLRET_ELIDE", title: "64 位 JIT 不使用调用返回影子栈", kind: .bool, defaultValue: "1", category: "x86 模拟（FEX）", note: "默认开启。64 位 ARM64EC JIT 不再维护 iOS 中无人读取的 FEX 调用返回影子栈，每次客户 CALL/RET 减少 9 条指令，并将链接调用改为 bl，使 CPU 返回预测器跟踪客户调用。设为 0 恢复影子栈，程序启动时读取。", choices: [], sources: ["FEX/Source/Windows/ARM64EC/Module.cpp"]),
        ConfigOption(key: "env.MADEIRA_FEX_EC_BITMAP_CACHE", title: "使用线程位图指针检查原生代码", kind: .bool, defaultValue: "1", category: "x86 模拟（FEX）", note: "默认开启。64 位 JIT 调度器通过线程状态保存的指针检查原生代码位图，避免遍历 TPIDRRO_EL0、TEB 和 PEB，每次经导入表调用系统 DLL 可减少 4 条指令。设为 0 恢复遍历，程序启动时读取。", choices: [], sources: ["FEX/Source/Windows/ARM64EC/Module.cpp"]),
        ConfigOption(key: "env.MADEIRA_FEX_EC_EXIT_LEAN", title: "精简 JIT 到原生代码的退出路径", kind: .bool, defaultValue: "1", category: "x86 模拟（FEX）", note: "AFP 关闭时默认开启。64 位 JIT 调用 ARM64EC 原生代码使用精简入口：省去 FPCR 读取，从线程状态读取 CPU 区域和暂停门铃，按线程而非原子方式计数，并从线程上次命中开始查找别名，从 44 条减至 31 条指令。xp-api 计数每线程滞后不足 64 次。设为 0 恢复旧入口，程序启动时读取。", choices: [], sources: ["FEX/Source/Windows/ARM64EC/Module.cpp"]),
        ConfigOption(key: "env.MADEIRA_FEX_EC_RET", title: "通过返回预测器从原生代码返回", kind: .bool, defaultValue: "1", category: "x86 模拟（FEX）", note: "默认开启。客户代码通过 BLR 离开 JIT 调用 ARM64EC 原生代码，返回时经 L1 查找后用 RET 返回，使 CPU 返回地址预测器保持同步，指令数由 22 减至 10。设为 0 恢复 BR 和调度循环，程序启动时读取。", choices: [], sources: ["FEX/Source/Windows/ARM64EC/Module.cpp"]),
        ConfigOption(key: "env.MADEIRA_FEX_EC_RET_DIRECT", title: "从原生代码直接返回 JIT", kind: .bool, defaultValue: "1", category: "x86 模拟（FEX）", note: "默认开启。原生 ARM64EC 函数返回游戏 x64 代码时直接进入 64 位 JIT，省去预先检查原生代码位图；调度器仍会检查尚无翻译的地址。每次系统 DLL 返回减少 11 条指令。设为 0 恢复预检查，程序启动时读取。", choices: [], sources: ["FEX/Source/Windows/ARM64EC/Module.cpp"]),
        ConfigOption(key: "env.MADEIRA_FEX_FAIL_CALLRET", title: "", kind: .text, defaultValue: "", category: "x86 模拟（FEX）", note: "使用 threadstate:N 可人为令第 N 次线程状态分配失败，用于验证内存区域耗尽时的故障隔离路径。", choices: [], sources: ["FEX/FEXCore/Source/Interface/Core/Core.cpp", "FEX/Source/Windows/Common/CallRetStack.h"]),
        ConfigOption(key: "env.MADEIRA_FEX_SMC_FASTPATH", title: "", kind: .text, defaultValue: "", category: "x86 模拟（FEX）", note: "控制自修改代码存储快速路径；设为 0 时恢复持锁路径。", choices: [], sources: ["FEX/Source/Windows/ARM64EC/Module.cpp"]),
        ConfigOption(key: "env.MADEIRA_IR_TOPO", title: "", kind: .text, defaultValue: "", category: "x86 模拟（FEX）", note: "每次编译优化遍结束后检查各基本块的 IR 节点拓扑，用于找出最先破坏链表结构的优化遍。", choices: [], sources: ["FEX/FEXCore/Source/Interface/IR/PassManager.cpp"]),
        ConfigOption(key: "env.MADEIRA_IR_TOPO_MIN", title: "", kind: .text, defaultValue: "", category: "x86 模拟（FEX）", note: "仅对较大的函数执行 IR 拓扑检查，避免对所有编译过程逐块检查造成明显性能开销。", choices: [], sources: ["FEX/FEXCore/Source/Interface/IR/PassManager.cpp"]),
        ConfigOption(key: "env.MADEIRA_IRCAP_MODULE", title: "", kind: .text, defaultValue: "", category: "x86 模拟（FEX）", note: "指定需要定向捕获 IR 的模块；模块映射后启用捕获，配合 MADEIRA_IRCAP_RVA 使用，便于无需重编译即可更换诊断目标。", choices: [], sources: ["FEX/Source/Windows/Common/InvalidationTracker.cpp"]),
        ConfigOption(key: "env.MADEIRA_IRCAP_RVA", title: "", kind: .text, defaultValue: "", category: "x86 模拟（FEX）", note: "指定需要定向捕获 IR 的模块内相对地址，配合 MADEIRA_IRCAP_MODULE 使用。", choices: [], sources: ["FEX/Source/Windows/Common/InvalidationTracker.cpp"]),
        ConfigOption(key: "env.MADEIRA_NO_DFE", title: "", kind: .text, defaultValue: "", category: "x86 模拟（FEX）", note: "控制禁用死标志消除优化，用于针对性排查 FEX 优化过程中 CPU 占用过高和登录后渲染停滞。", choices: [], sources: ["FEX/FEXCore/Source/Interface/IR/PassManager.cpp"]),
